#!/usr/bin/env node
// Generates docs/rules.md from the rule metadata so the docs never drift from the code.
import { writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { RULES } from '../dist/index.js';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const ICON = { critical: '\u{1F7E3}', high: '\u{1F534}', medium: '\u{1F7E0}', low: '\u{1F535}', info: '\u26AA' };

const lines = [
  '# Rules',
  '',
  '<!-- Generated by `npm run docs`. Edit the rule metadata in src/rules/, not this file. -->',
  '',
  `bekci ships ${RULES.length} rules. Severities are defaults; some rules raise or lower severity based on context ` +
    '(for example, `curl | sh` is high in a hook but medium in documentation).',
  '',
  '| ID | Rule | Default severity | Category |',
  '| --- | --- | --- | --- |',
  ...RULES.map((r) => `| [${r.id}](#${r.id.toLowerCase()}) | ${r.title} | ${ICON[r.severity]} ${r.severity} | ${r.category} |`),
  '',
];

for (const r of RULES) {
  lines.push(
    `## ${r.id}`,
    '',
    `**${r.title}** \u00B7 \`${r.name}\` \u00B7 ${ICON[r.severity]} ${r.severity} \u00B7 ${r.category}`,
    '',
  );
  lines.push(r.description, '', `**Fix:** ${r.remediation}`, '');
  if (r.references?.length) lines.push('**References:**', '', ...r.references.map((u) => `- <${u}>`), '');
  lines.push(
    r.severity === 'critical'
      ? `Suppress: \`--ignore ${r.id}\` or \`"ignore": ["${r.id}"]\` in \`.bekci.json\`. Critical findings cannot be silenced with inline comments.`
      : `Suppress: \`--ignore ${r.id}\`, \`"ignore": ["${r.id}"]\` in \`.bekci.json\`, or a \`bekci-ignore ${r.id}\` comment on the line (project files only).`,
    '',
  );
}

writeFileSync(path.join(root, 'docs', 'rules.md'), lines.join('\n'));
console.log(`wrote docs/rules.md (${RULES.length} rules)`);
